mapper.select:
SELECT COUNT(*) 
FROM project_equipment 
WHERE project_id = #{projectId} AND rental_id = #{rentalId}

SELECT er.id AS rentalId, er.equipment_id AS equipmentId, er.user_id AS addedBy, e.name AS equipmentName, u.name AS renterName, er.purpose FROM equipment_rentals er LEFT JOIN equipment e ON er.equipment_id = e.id LEFT JOIN users u ON er.user_id = u.id WHERE er.user_id IN
#{memberId}
AND er.return_date IS NULL AND er.is_approved = TRUE AND er.status IN ('APPROVED', 'RENTED') AND NOT EXISTS ( SELECT 1 FROM project_equipment pe WHERE pe.project_id = #{projectId} AND pe.rental_id = er.id ) ORDER BY er.rent_date DESC, u.name ASC
